// Digital twin for Drive.DC.H — TI DRV8214 brushed-DC H-bridge motor driver.
//
// 11 V / 2 A H-bridge with integrated current sense (IPROPI/NPROP), voltage &
// current regulation, stall detection, and sensorless ripple counting (speed +
// position without an encoder). I²C control on pads 4/5; the H-bridge drives a
// motor across OUT1 (pad 8) / OUT2 (pad 7) — per the tile schematic, which is
// authoritative; NPROP (pad 6) mirrors motor current. (The tile JSON currently
// lists pad 7=OUT1 / 8=OUT2 — swapped; correct it at the product DB.)
// Address 0x34 = A1/A0 both Hi-Z — the dual-NP (unpopulated-resistor) default;
// alternate SKUs would populate the address resistors.
//
// The motor is external, so its current/speed are MODELED from a load control
// (the VM draw is dominated by motor current, like a piezo's reactive draw is
// the whole story for Drive.P). The chip's own currents are canonical from the
// datasheet (VM active 1.3 mA / sleep ~0.1 µA; VCC active 1.5 mA), and the
// readback conversions match the driver: Vmtr = raw·FS/255 (FS 15.7 V or 3.92 V),
// Imtr = raw·Imax/192, 8-bit speed, 16-bit ripple count, FAULT bit masks.
import type { TileSim } from '../tileSim';

const I2C_ADDR = 0x34; // A1/A0 Hi-Z (dual-NP default)

// CS_GAIN_SEL → max current (mA), matching the driver's cs_max_ma table
const CS_MAX_MA = [4000, 2000, 1000, 500, 250, 125, 250, 125];

// bridge state
const COAST = 0;
const FORWARD = 1;
const REVERSE = 2;
const BRAKE = 3;

// FAULT register bits
const FLT_FAULT = 0x80;
const FLT_STALL = 0x20;
const FLT_OCP = 0x10;

// chip supply currents (µA), datasheet Table 7.5
const IVM_ACTIVE_UA = 1300; // VM active quiescent
const IVM_SLEEP_UA = 0.1; // VM sleep (OVP enabled)
const IVCC_ACTIVE_UA = 1500; // VCC/V+ active

const UVLO_MV = 1800; // VM minimum

interface State {
  // ── inputs (controls) ──
  vm_mv: number; // motor supply (VM)
  vplus_mv: number; // logic supply (V+)
  bridge: number; // 0 coast, 1 forward, 2 reverse, 3 brake
  target: number; // WSET_VSET duty/voltage target, 0..255
  load: number; // mechanical load 0..100 % (→ current ↑, speed ↓)
  stall: number; // rotor stalled
  fault: number; // inject overcurrent fault
  sleeping: number; // EN_OUT = 0

  // ── config (tracked) ──
  vm_gain: number; // 0 = 0-15.7 V range, 1 = 0-3.92 V
  cs_gain: number; // CS_GAIN_SEL 0..5
  control_mode: number; // 0 I2C, 1 PAD_PHEN, 2 PAD_IN1IN2
  reg_mode: number; // 0 open, 1 cycle-by-cycle, 2 speed, 3 voltage
  imode: number; // current-regulation mode
  stall_enabled: number;
  inrush_ms: number;
  stall_recovery: number;
  ripple_thr: number;
  filter_gain: number;

  // ── evolving ──
  ripple_count: number; // accumulates while running

  [field: string]: number;
}

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

const csMax = (s: State) => CS_MAX_MA[clamp(Math.round(s.cs_gain), 0, 7)];
const voltFs = (s: State) => (s.vm_gain === 1 ? 3920 : 15700);
const running = (s: State) =>
  s.sleeping !== 1 && s.vm_mv >= UVLO_MV && (s.bridge === FORWARD || s.bridge === REVERSE);

// Regulated motor terminal voltage (mV): target maps onto the voltage range,
// clamped to the available supply. Zero unless actively driving.
function appliedMv(s: State): number {
  if (!running(s)) return 0;
  return Math.min(Math.round((s.target / 255) * voltFs(s)), s.vm_mv);
}

// Motor current (mA): a stalled rotor draws the gain's max (locked-rotor); a
// running motor scales with duty and mechanical load. External motor ⇒ modeled.
function motorMa(s: State): number {
  if (!running(s)) return 0;
  if (s.stall === 1) return csMax(s);
  const i = (0.15 + 0.85 * (s.load / 100)) * (s.target / 255) * csMax(s);
  return Math.round(clamp(i, 0, csMax(s)));
}

// Speed estimate (0..255, the chip's RC_STATUS1 scale): rises with duty, falls
// with load; zero when stalled or not driving.
function speed(s: State): number {
  if (!running(s) || s.stall === 1) return 0;
  return Math.round(clamp((s.target / 255) * (1 - 0.6 * (s.load / 100)) * 255, 0, 255));
}

function faultByte(s: State): number {
  let b = 0;
  if (s.stall === 1) b |= FLT_STALL;
  if (s.fault === 1) b |= FLT_OCP;
  return b ? b | FLT_FAULT : 0;
}

const sim: TileSim<State> = {
  tile: 'Drive.DC.H',

  defaultState: {
    vm_mv: 5000,
    vplus_mv: 3300,
    bridge: COAST,
    target: 255,
    load: 30,
    stall: 0,
    fault: 0,
    sleeping: 0,

    vm_gain: 1,
    cs_gain: 0,
    control_mode: 0,
    reg_mode: 3,
    imode: 1,
    stall_enabled: 1,
    inrush_ms: 0,
    stall_recovery: 1,
    ripple_thr: 0,
    filter_gain: 1,

    ripple_count: 0,
  },

  controls: [
    { type: 'slider', field: 'bridge', label: 'Bridge (0c 1f 2r 3b)', min: 0, max: 3, step: 1 },
    { type: 'slider', field: 'target', label: 'Target (duty)', min: 0, max: 255, step: 1 },
    {
      type: 'slider',
      field: 'load',
      label: 'Mechanical load',
      min: 0,
      max: 100,
      step: 1,
      unit: '%',
    },
    {
      type: 'slider',
      field: 'vm_mv',
      label: 'VM (motor supply)',
      min: 1800,
      max: 11000,
      step: 100,
      unit: 'mV',
    },
    { type: 'slider', field: 'cs_gain', label: 'Current-sense gain', min: 0, max: 5, step: 1 },
    { type: 'toggle', field: 'vm_gain', label: 'Low-V range (3.92 V)' },
    { type: 'toggle', field: 'stall', label: 'Stall rotor' },
    { type: 'toggle', field: 'fault', label: 'Overcurrent fault' },
    { type: 'toggle', field: 'sleeping', label: 'Sleep' },
  ],

  // Ripple counter accumulates while the motor turns (8-bit speed → counts).
  deriveState(state) {
    if (!running(state) || state.stall === 1) return {};
    return { ripple_count: clamp(state.ripple_count + Math.round(speed(state) / 16), 0, 0xffff) };
  },

  hostCalls: {
    // ── lifecycle ──
    tile_drive_dc_h_find: () => ({ scalar: I2C_ADDR }),
    tile_drive_dc_h_init: () => ({
      scalar: 0,
      nextState: { bridge: COAST, sleeping: 0, reg_mode: 3, control_mode: 0, ripple_count: 0 },
    }),
    tile_drive_dc_h_sleep: () => ({ nextState: { sleeping: 1 } }),
    tile_drive_dc_h_wake: () => ({ nextState: { sleeping: 0 } }),

    // ── bridge control ──
    tile_drive_dc_h_forward: () => ({ nextState: { bridge: FORWARD, sleeping: 0 } }),
    tile_drive_dc_h_reverse: () => ({ nextState: { bridge: REVERSE, sleeping: 0 } }),
    tile_drive_dc_h_brake: () => ({ nextState: { bridge: BRAKE } }),
    tile_drive_dc_h_coast: () => ({ nextState: { bridge: COAST } }),
    tile_drive_dc_h_set_target: ({ args }) => ({
      nextState: { target: clamp(pick(args, 0, 255), 0, 255) },
    }),

    // ── configuration ──
    tile_drive_dc_h_set_control_mode: ({ args }) => ({
      nextState: { control_mode: pick(args, 0, 0) },
    }),
    tile_drive_dc_h_set_regulation_mode: ({ args }) => ({
      nextState: { reg_mode: pick(args, 0, 3) },
    }),
    tile_drive_dc_h_set_current_regulation_mode: ({ args }) => ({
      nextState: { imode: pick(args, 0, 1) },
    }),
    tile_drive_dc_h_set_current_sense_gain: ({ args }) => ({
      nextState: { cs_gain: clamp(pick(args, 0, 0), 0, 7) },
    }),
    tile_drive_dc_h_set_stall_enabled: ({ args }) => ({
      nextState: { stall_enabled: pick(args, 0, 1) ? 1 : 0 },
    }),
    tile_drive_dc_h_set_inrush_time_ms: ({ args }) => ({
      nextState: { inrush_ms: pick(args, 0, 0) },
    }),
    tile_drive_dc_h_set_stall_recovery: ({ args }) => ({
      nextState: { stall_recovery: pick(args, 0, 1) },
    }),
    tile_drive_dc_h_set_ripple_threshold: ({ args }) => ({
      nextState: { ripple_thr: pick(args, 0, 0) },
    }),
    tile_drive_dc_h_set_ripple_filter_gain: ({ args }) => ({
      nextState: { filter_gain: pick(args, 0, 1) },
    }),

    // ── status / readback ──
    tile_drive_dc_h_get_fault: ({ state }) => ({ scalar: faultByte(state) }),
    tile_drive_dc_h_clear_fault: () => ({ nextState: { fault: 0, stall: 0 } }),
    tile_drive_dc_h_is_stalled: ({ state }) => ({ scalar: state.stall }),
    tile_drive_dc_h_get_voltage_mv: ({ state }) => ({ scalar: appliedMv(state) }),
    tile_drive_dc_h_get_current_ma: ({ state }) => ({ scalar: motorMa(state) }),
    tile_drive_dc_h_get_speed: ({ state }) => ({ scalar: speed(state) }),
    tile_drive_dc_h_get_ripple_count: ({ state }) => ({ scalar: state.ripple_count }),
    tile_drive_dc_h_clear_ripple_count: () => ({ nextState: { ripple_count: 0 } }),
    tile_drive_dc_h_is_running: ({ state }) => ({ scalar: running(state) ? 1 : 0 }),
    tile_drive_dc_h_wait_for_stop: () => ({ scalar: 1 }), // can't block in the sim

    // ── tier-2 helpers ──
    tile_drive_dc_h_set_speed_rpm: ({ args }) => ({
      nextState: { bridge: pick(args, 1, 0) === 1 ? REVERSE : FORWARD, reg_mode: 2, sleeping: 0 },
    }),
    tile_drive_dc_h_move_distance: ({ args }) => ({
      nextState: {
        bridge: pick(args, 1, 0) === 1 ? REVERSE : FORWARD,
        sleeping: 0,
        ripple_count: 0,
      },
    }),
  },

  provenance: {
    // canonical — datasheet/driver-accurate
    tile_drive_dc_h_find: 'canonical', // I2C 0x34 (Hi-Z/Hi-Z)
    tile_drive_dc_h_get_voltage_mv: 'canonical', // Vmtr = raw·FS/255
    tile_drive_dc_h_get_current_ma: 'canonical', // Imtr scale (CS_GAIN_SEL)
    tile_drive_dc_h_get_fault: 'canonical', // FAULT bit masks
    tile_drive_dc_h_forward: 'canonical', // OUT1=H, OUT2=L
    tile_drive_dc_h_reverse: 'canonical', // OUT1=L, OUT2=H
    tile_drive_dc_h_brake: 'canonical', // both low
    tile_drive_dc_h_coast: 'canonical', // both Hi-Z
    tile_drive_dc_h_set_current_sense_gain: 'canonical', // CS_GAIN_SEL codes
    tile_drive_dc_h_set_control_mode: 'canonical',
    tile_drive_dc_h_set_regulation_mode: 'canonical',
    // inferred — behavior obvious from the driver; motor response modeled
    tile_drive_dc_h_init: 'inferred',
    tile_drive_dc_h_sleep: 'inferred',
    tile_drive_dc_h_wake: 'inferred',
    tile_drive_dc_h_set_target: 'inferred',
    tile_drive_dc_h_set_current_regulation_mode: 'inferred',
    tile_drive_dc_h_set_stall_enabled: 'inferred',
    tile_drive_dc_h_set_inrush_time_ms: 'inferred',
    tile_drive_dc_h_set_stall_recovery: 'inferred',
    tile_drive_dc_h_set_ripple_threshold: 'inferred',
    tile_drive_dc_h_set_ripple_filter_gain: 'inferred',
    tile_drive_dc_h_clear_fault: 'inferred',
    tile_drive_dc_h_is_stalled: 'inferred',
    tile_drive_dc_h_get_speed: 'inferred', // modeled from duty × load
    tile_drive_dc_h_get_ripple_count: 'inferred', // accumulated from modeled speed
    tile_drive_dc_h_clear_ripple_count: 'inferred',
    tile_drive_dc_h_is_running: 'inferred',
    tile_drive_dc_h_set_speed_rpm: 'inferred',
    tile_drive_dc_h_move_distance: 'inferred',
    // hallucinated — not really modeled
    tile_drive_dc_h_wait_for_stop: 'hallucinated', // always reports stopped
    power: 'inferred', // motor current modeled; chip quiescent canonical
  },

  // H-bridge terminals (drive level 0..1) + NPROP current mirror.
  padOutputs(state) {
    const d = running(state) ? state.target / 255 : 0;
    const out1 = state.bridge === FORWARD ? d : 0;
    const out2 = state.bridge === REVERSE ? d : 0;
    const nprop = motorMa(state) / csMax(state);
    return { OUT1: out1, OUT2: out2, NPROP: nprop };
  },

  // Electrical. V+ logic (pad 10) + VM motor supply (pad 9, carries the motor
  // current — the dominant draw); H-bridge terminals OUT1 (pad 8) / OUT2 (pad 7).
  power(state) {
    const asleep = state.sleeping === 1;
    const uvlo = state.vm_mv < UVLO_MV;
    const vccUa = asleep || uvlo ? 0 : IVCC_ACTIVE_UA;
    const vmChipUa = asleep ? IVM_SLEEP_UA : uvlo ? 0 : IVM_ACTIVE_UA;
    const motorUa = motorMa(state) * 1000;
    const vmUa = vmChipUa + motorUa;
    const av = appliedMv(state);

    return {
      draw_ua: Math.round(vccUa + vmUa),
      rails: [
        {
          name: 'V+',
          role: 'supply',
          v_mv: state.vplus_mv,
          i_ua: vccUa,
          pads: ['10'],
          note: 'logic supply',
        },
        {
          name: 'VM',
          role: 'supply',
          v_mv: state.vm_mv,
          i_ua: Math.round(vmUa),
          pads: ['9'],
          note: asleep
            ? 'motor supply — sleep'
            : motorUa > 0
              ? 'motor supply + motor current'
              : 'motor supply — idle',
        },
        {
          name: 'OUT1',
          role: 'output',
          v_mv: state.bridge === FORWARD ? av : 0,
          pads: ['8'],
          note: 'H-bridge terminal 1 (chip OUT1 → tile pad 8)',
        },
        {
          name: 'OUT2',
          role: 'output',
          v_mv: state.bridge === REVERSE ? av : 0,
          pads: ['7'],
          note: 'H-bridge terminal 2 (chip OUT2 → tile pad 7)',
        },
      ],
    };
  },
};

export default sim;
